def corner_fill(Ain, base):
    # fill exterior background cell x if it forms a 2x2 with two diagonally-adjacent ring cells
    fill = np.zeros_like(base)
    Rr,Cc=Ain.shape
    for r in range(Rr-1):
        for c in range(Cc-1):
            blk = [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            vals = [base[a,b] for a,b in blk]
            ones = [blk[i] for i,v in enumerate(vals) if v]
            if len(ones)==2 and abs(ones[0][0]-ones[1][0])==1 and abs(ones[0][1]-ones[1][1])==1:
                for cell in blk:
                    if not base[cell]: fill[cell]=True
    return fill
