def ext_mask(Ain):
    Rr,Cc=Ain.shape
    bg=Ain==0
    # 8-conn flood from border
    free=np.zeros_like(bg)
    dq=deque()
    for r in range(Rr):
        for c in range(Cc):
            if bg[r,c] and (r in(0,Rr-1) or c in(0,Cc-1)):
                free[r,c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
