def enc_classes(Gi,Go=None):
    R,C=Gi.shape
    w4=wcount4b(Gi); em=ext_mask(Gi)
    cnt=Counter(); cells={}
    for r in range(R):
        for c in range(C):
            if Gi[r,c]==1 or em[r,c]: continue
            w8=sum(Gi[r+dr,c+dc]==1 for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc) and 0<=r+dr<R and 0<=c+dc<C)
            w8d=1 if any(Gi[r+dr,c+dc]==1 for dr in(-1,0,1) for dc in(-1,0,1) if dr and dc and 0<=r+dr<R and 0<=c+dc<C) else 0
            key=(int(w4[r,c]),w8d)
            cnt[key]+=1
            cells.setdefault(key,[]).append((r,c,int(Go[r,c]) if Go is not None else None))
    return cnt,cells
for name,Gi,Go in [('d1',I,O),('d3',A,B),('d4',A4,B4),('T',T,None)]:
    cnt,cells=enc_classes(Gi,Go)
    print(name,dict(sorted(cnt.items())))
    for k,v in sorted(cells.items()):
        golds={g for (_,_,g) in v}
        print('  ',k,len(v),'golds:',golds)

